      "processor_id": "example-proc",
      "created_date": "2025-03-26T15:05:00.000Z",
      "updated_date": "2025-03-26T15:05:01.000Z",
      "payment_details": {
        "card_number": "4***********1111",
        "card_exp": "1226",
        "card_type": "Visa",
        "card_bin": "411111"
